        etapes: [
          ['القاعدة', 'إذا ظهر المقام عاملا في البسط فإنّه يُبسَّط دون إنطاق'],
          ['نستعمل السؤال السابق', '-34 + 13√3 = (2√3 - 1)(4 - 5√3)'],
          ['نعوّض في البسط', '(-34 + 13√3)/(4 - 5√3) = (2√3 - 1)(4 - 5√3)/(4 - 5√3)'],
          ['نبسّط', '(2√3 - 1)(4 - 5√3)/(4 - 5√3) = 2√3 - 1'],
          ['نطرح 2', 'a = 2√3 - 1 - 2'],
          ['النتيجة', 'a = 2√3 - 3']
        ],
