          ['و M مركز ثقل المثلّث', 'إذن M تنتمي إلى كلّ متوسّط'],
          ['إذن M من [BN]', 'BN = 8'],
          ['نتحقّق من الثلثين', 'BM = 16/3'],
          ['و من الثلث الآخر', 'MN = 8/3'],
          ['النتيجة', 'النقاط B و M و N على استقامة واحدة']
