  // =========================================================================
  // الحصّة 12 — التمرين 5   (un équilatéral, et son symétrique)
  //
  //   ABC équilatéral de côté 6, I milieu de [BC], donc AI = 3√3. O symétrique
  //   de B par rapport à A : A devient le milieu de [OB], et comme AC = 6 est
  //   le rayon du cercle de diamètre [OB], le triangle OBC est RECTANGLE EN C.
  //
  //   Ensuite tout est centre de gravité : G sur [AC] avec GA/GC = 1/2 est le
  //   centre de gravité de OBC (car CA en est une médiane, et CG = 4 en est les
  //   deux tiers), et (JI) — la droite des milieux — donne le rectangle AMCI.
